// Regenerates lib/ava/food/index.ts from the files in lib/ava/food/data/.
// Run after adding a country or region:  node scripts/gen-food-index.mjs
import { readdirSync, writeFileSync } from 'node:fs';
const dir = new URL('../lib/ava/food/data/', import.meta.url);
const slugs = readdirSync(dir).filter(f => f.endsWith('.ts')).map(f => f.slice(0, -3)).sort();
const ident = s => '_' + s.replace(/-/g, '_');
const out = [
  '// GENERATED by scripts/gen-food-index.mjs — do not edit by hand.',
  "import { expand, type Food } from './types';",
  ...slugs.map(s => `import { foods as ${ident(s)} } from './data/${s}';`),
  '',
  'export const FOOD_LISTS: Record<string, Food[]> = {',
  ...slugs.map(s => `  '${s}': expand(${ident(s)}),`),
  '};',
  '',
].join('\n');
writeFileSync(new URL('../lib/ava/food/index.ts', import.meta.url), out);
console.log(`index.ts: ${slugs.length} lists`);
